// Differential test of parseDate against dateutil.parser.parse 2.9.0.
// The corpus (generated by tools/fixtures/generate_dateutil.py) holds
// thousands of structured, hand-picked and random date strings with
// dateutil's result for each, in UTC and in America/New_York.

import { readFileSync } from 'node:fs';

import { describe, expect, it } from 'vitest';

import { withTz } from '../test/tz';
import { PyDateTime } from './datetime';
import { DateParseError, parseDate } from './timestamps';

interface Corpus {
  default: string;
  currentYear: number;
  zone: string;
  cases: [string, string, string][];
  otherZones: Record<string, Record<string, [string, string]>>;
}

const corpus = JSON.parse(
  readFileSync(
    new URL('__fixtures__/dateutil-corpus.json', import.meta.url),
    'utf8',
  ),
) as Corpus;

const [year = 0, month = 0, day = 0] = corpus.default
  .slice(0, 10)
  .split('-')
  .map(Number);
const options = {
  currentYear: corpus.currentYear,
  default: new PyDateTime({ day, month, year }),
};

/** The TS outcome in the corpus's terms: [kind, text]. */
function outcome(input: string): [string, string] {
  try {
    return ['ok', parseDate(input, options).isoformat()];
  } catch (error) {
    if (error instanceof DateParseError) {
      return ['ParserError', error.message];
    }
    if (error instanceof RangeError) {
      // Python raises OverflowError from datetime.replace, or a ValueError
      // when an out-of-range offset is first used.
      const kind = error.message.startsWith('offset must be')
        ? 'late:ValueError'
        : 'OverflowError';
      return [kind, error.message];
    }
    throw error;
  }
}

function mismatches(
  zone: string,
  expected: (index: number) => [string, string],
): string[] {
  return withTz(zone, () =>
    corpus.cases.flatMap(([input], index) => {
      const want = expected(index);
      const got = outcome(input);
      return got[0] === want[0] && got[1] === want[1]
        ? []
        : [
            `${JSON.stringify(input)}: want ${want.join(' ')} got ${got.join(' ')}`,
          ];
    }),
  );
}

describe('parseDate matches dateutil', () => {
  it(`on ${corpus.cases.length} strings in ${corpus.zone}`, () => {
    const failures = mismatches(corpus.zone, index => {
      const [, kind = '', text = ''] = corpus.cases[index] ?? [];
      return [kind, text];
    });
    expect(failures).toEqual([]);
  });

  for (const [zone, diffs] of Object.entries(corpus.otherZones)) {
    it(`on the same strings in ${zone}`, () => {
      const failures = mismatches(zone, index => {
        const [, kind = '', text = ''] = corpus.cases[index] ?? [];
        return diffs[String(index)] ?? [kind, text];
      });
      expect(failures).toEqual([]);
    });
  }
});
